using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "MultipleSoulHeatTierCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Sothis/MultipleSoulHeatTierCustomDescription", order = 0)]
public class MultipleSoulHeatTierCustomDescription : MultipleActionCustomDescription
{
	protected enum ActionType
	{
		FIRSTACTION,
		SECONDACTION,
		THIRDACTION
	}

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		MultipleSoulHeatTierAction multipleSoulHeatTierAction = battleAction as MultipleSoulHeatTierAction;
		string text = "";
		int num = 100000;
		if (IsAddHighlight())
		{
			num = multipleSoulHeatTierAction.GetSoulHeatAmountToUse(activateFeedback: false);
		}
		int num2 = (multipleSoulHeatTierAction.EnableVariableActionSoulHeatAmountToUse ? GetFinalAmountWithoutEquation(amountModified) : 10);
		text = text + GetActionFormattedDescription(multipleSoulHeatTierAction, multipleSoulHeatTierAction.BattleAction, num2, multipleSoulHeatTierAction.VariableActionValue ? GetFinalAmountWithoutEquation(amountModified) : multipleSoulHeatTierAction.ActionValue, num >= num2, multipleSoulHeatTierAction.CheckDecreaseSoulHeatOnFirstAction || multipleSoulHeatTierAction.CheckDecreaseSoulHeatOnFirstAndSecondAction, ActionType.FIRSTACTION) + "\n";
		int num3 = (multipleSoulHeatTierAction.EnableVariableActionSoulHeatAmountToUse ? (GetFinalAmountWithoutEquation(amountModified) - 1) : 9);
		text = text + GetActionFormattedDescription(multipleSoulHeatTierAction, multipleSoulHeatTierAction.SecondBattleAction, multipleSoulHeatTierAction.SecondActionSoulHeatAmountToUse, multipleSoulHeatTierAction.SecondActionValue, num < num3 && num >= multipleSoulHeatTierAction.SecondActionSoulHeatAmountToUse, multipleSoulHeatTierAction.CheckDecreaseSoulHeatOnFirstAndSecondAction, ActionType.SECONDACTION) + "\n";
		if (!multipleSoulHeatTierAction.DisableThirdAction)
		{
			text += GetActionFormattedDescription(multipleSoulHeatTierAction, multipleSoulHeatTierAction.ThirdBattleAction, 0, multipleSoulHeatTierAction.ThirdActionValue, num < multipleSoulHeatTierAction.SecondActionSoulHeatAmountToUse, checkDecreaseSoulHeatOnAction: false, ActionType.THIRDACTION);
		}
		if (!multipleSoulHeatTierAction.CheckDecreaseSoulHeatOnFirstAction && !multipleSoulHeatTierAction.CheckDecreaseSoulHeatOnFirstAndSecondAction)
		{
			text = GetResetDecreaseSoulHeatDescription(multipleSoulHeatTierAction, text);
		}
		return text;
	}

	protected string GetActionFormattedDescription(MultipleSoulHeatTierAction multipleSoulHeatTierAction, BattleAction action, int minimumSoulHeatAmount, int actionValue, bool addHighlight, bool checkDecreaseSoulHeatOnAction, ActionType actionType)
	{
		string minimumSoulHeatLocalized = multipleSoulHeatTierAction.GetMinimumSoulHeatLocalized(minimumSoulHeatAmount);
		string text = "";
		if (actionType == ActionType.FIRSTACTION && multipleSoulHeatTierAction.DisableBattleActionVariable)
		{
			text = CustomFirstActionDescription(multipleSoulHeatTierAction);
		}
		else if (actionType == ActionType.SECONDACTION && multipleSoulHeatTierAction.DisableSecondBattleActionVariable)
		{
			text = CustomSecondActionDescription(multipleSoulHeatTierAction);
		}
		else if (actionType == ActionType.THIRDACTION && multipleSoulHeatTierAction.IncreaseSoulHeatBySecondActionSoulHeatAmountOnThirdAction)
		{
			text = action.GetActionDescription(actionValue);
			text = text + "\n" + base.localizationManager.GetLocalizedIncreasesSoulHeatHeatID(multipleSoulHeatTierAction.SecondActionSoulHeatAmountToUse).UppercaseFirst();
		}
		else if (actionType == ActionType.THIRDACTION && multipleSoulHeatTierAction.IncreaseSoulHeatByFixedAmountOnThirdAction)
		{
			text = action.GetActionDescription(actionValue);
			text = text + "\n" + base.localizationManager.GetLocalizedIncreasesSoulHeatHeatID(multipleSoulHeatTierAction.SoulHeatIncreaseFixedAmountOnThirdAction).UppercaseFirst();
		}
		else
		{
			text = action.GetActionDescription(actionValue);
		}
		string text2 = string.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedActionTopicFormat(), minimumSoulHeatLocalized.RemoveLast(), text);
		if (checkDecreaseSoulHeatOnAction)
		{
			text2 = GetResetDecreaseSoulHeatDescription(multipleSoulHeatTierAction, text2);
		}
		if (IsAddHighlight() && addHighlight)
		{
			text2 = GetHighlightedDescription(text2);
		}
		return text2;
	}

	private string GetResetDecreaseSoulHeatDescription(MultipleSoulHeatTierAction multipleSoulHeatTierAction, string description)
	{
		if (multipleSoulHeatTierAction.ResetSoulHeatAfterUse)
		{
			description = description + "\n" + ((!multipleSoulHeatTierAction.CheckDecreaseSoulHeatOnFirstAction && !multipleSoulHeatTierAction.CheckDecreaseSoulHeatOnFirstAndSecondAction) ? "\n" : "") + base.localizationManager.GetLocalizedResetSoulHeat();
		}
		else if (multipleSoulHeatTierAction.DecreaseSoulHeat)
		{
			description = description + "\n" + ((!multipleSoulHeatTierAction.CheckDecreaseSoulHeatOnFirstAction && !multipleSoulHeatTierAction.CheckDecreaseSoulHeatOnFirstAndSecondAction) ? "\n" : "") + multipleSoulHeatTierAction.GetDecreaseSoulHeatLocalized();
		}
		return description;
	}

	protected virtual string CustomFirstActionDescription(MultipleSoulHeatTierAction multipleSoulHeatTierAction)
	{
		return "";
	}

	protected virtual string CustomSecondActionDescription(MultipleSoulHeatTierAction multipleSoulHeatTierAction)
	{
		if (multipleSoulHeatTierAction.IncreaseSoulHeatOnSecondAction)
		{
			return base.localizationManager.GetLocalizedIncreasesSoulHeatHeatID(multipleSoulHeatTierAction.SecondActionValue).UppercaseFirst();
		}
		return "";
	}
}
